import{_ as t,H as a,f as n,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语 | 人生的价值就在于创造","description":"","frontmatter":{},"headers":[],"relativePath":"LangChain实战课/结束语｜人生的价值就在于创造.md","filePath":"LangChain实战课/结束语｜人生的价值就在于创造.md","lastUpdated":1795530794000}'),s={name:"LangChain实战课/结束语｜人生的价值就在于创造.md"};function p(E,e,o,r,g,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="结束语-人生的价值就在于创造" tabindex="-1">结束语 | 人生的价值就在于创造 <a class="header-anchor" href="#结束语-人生的价值就在于创造" aria-label="Permalink to &quot;结束语 | 人生的价值就在于创造&quot;">​</a></h1><p>你好，我是黄佳。</p><p>时间过得真快，转眼间就到了本专栏的最后一节课，我想为坚持学到最后的你大声鼓掌，也很开心能将我的阶段性沉淀传递出去，相信此刻的你已经体验到了 LangChain 的魅力。</p><p>技术上的进步，还需要你不断去练习，因为我深知：动手实践，比千言万语更有力量。所以在结束语中，我们不再谈技术细节，只分享一点我近期的感悟吧！如果我们恰好有共鸣，那就太棒了。</p><p>某一个深夜，SpaceX 研发的最新一代运载火箭系统“星舰”升空，但在发射仅 3 分钟后，“超重型推进器”未能与“星舰”分离，在高空解体。</p><p>不过，SpaceX CEO 马斯克没有太多的情绪，他在推特写道：“恭喜 SpaceX 团队令人兴奋的星舰试射，这为几个月后的下一次试射积累了许多经验。”马斯克希望在 10 年内建造 1000 艘“星舰”登陆火星，使人类成为跨行星物种的愿景不变。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>仰望苍穹，宇宙浩瀚。每每想起人类已在月球上留下脚印，而今又要再度出发，就不由在心中感慨：如此有幸，能生活在这个时代。如此有幸，能见证通用人工智能时代的到来！</p><p>是的，人类见证过一次次的历史时刻，现在，我们又站在另一个历史的节点上——通用人工智能的诞生。这并不仅仅是一个技术的进步，更是对未来世界的重新塑造。让我深感幸运的是，即便 AI 如此发达，有些东西仍是不可替代的，那就是人的创造力和情感。</p><p>也许，人生的真正价值并不仅仅是在于我们拥有了什么，计划了什么，更是在于我们创造了什么。创造意味着超越了现有的限制，突破了旧的境界，向着未知前行。而在这个愈发高速的时代，我们正在共同见证各种壮观的创造。</p><p>LangChain，这一新型的开发范式，也是一个绝佳的例证。LangChain，或者说基于 LLM 的智能开发框架，最吸引我的地方，就是凸显了代理的自主性。与传统固定逻辑的开发方式相比，有了大模型的推理能力和 ReAct 等框架，就带给了它更高的灵活性、更强的自适应能力、更好的可扩展性和更高效的开发。这是一个创新的设计，能够充分释放人的创造力，应对未知的挑战。</p><p>AI，把计算机程序从人类的工具进化成了智能的代理。</p><p>相信学完了 LangChain 课程的你，能够非常了解我想强调的这一点，也是我们这个专栏的核心价值。</p><p>前几天，在极客时间的部落里面，我贴了几张女儿的画作，同时抛出了一个问题：AIGC 来了，人类画师还有价值吗？</p><ul><li>一位朋友回答：当然有价值，抛开现在大部分 AI 绘画都是在拼图，还有一个就是人在画中注入的情感、寄托，比如图 2，如果 AI 作图，只能画出“母亲”的形象，您女儿画出的才是“妈妈”。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" alt=""></a></p><p>的确是这样的，她在纸上展现的不仅仅是线条和颜色，更是她的情感、她的视界、她的梦想。当 AI 能够绘画时，它可能会画出“母亲”的形象，但只有人能够画出“妈妈”。这是我们的情感、记忆和经历给予的，是无法复制的。</p><p>我们的《LangChain 实战课》也是一样，无论是我的课程设计，还是编辑老师的心力注入、耐心打磨，乃至你的刻苦学习、留言讨论，无不汇聚了我们彼此的情感和信心、认可和期盼。这就是专属于我们人类的创造。</p><p>因此，不论是探索外太空，还是深挖技术的内涵，或是简简单单的一笔一划，都证明了一个事实：人生的价值就在于创造。只有创造，我们才能真正感知到生命的深度，感受到存在的意义。让我们一起，以学习者的心态，拥抱这个充满无限可能的未来，创造更多的美好！</p><p>最后，这里有一份结课问卷，期待你谈谈对这门课程的学习体验，建议或意见都欢迎指出。我们会根据你的反馈持续迭代课程，让知识长久传递，常看常新。</p>',21)])])}const l=t(s,[["render",p]]);export{c as __pageData,l as default};
